import { useState } from 'react';
import Axios from 'axios';
import { useNavigate } from 'react-router-dom';
// @mui
import { Stack, IconButton, InputAdornment, TextField, Checkbox, Typography } from '@mui/material';
import { LoadingButton } from '@mui/lab';
// components
import Iconify from '../../../components/iconify';

import config from '../../../config.json'
import getConfig from '../../../configService';

config.apiUrl= await getConfig()




// ----------------------------------------------------------------------

export default function LoginForm() {
  const navigate = useNavigate();

  const [showPassword, setShowPassword] = useState(false);

  const [primeiroLogin, setPrimeiroLogin] = useState(false);

  // const [awake, setAwake] = useState(false);

  const [cfgAll, setCfgAll] = useState();

  const [values, setValues] = useState({
    email: '',
    password: '',
    confirmpassword: ''
  })
  


  // 'Acordar' a api
  /*
  if(!awake){
    Axios.post(`${config.apiUrl}/sendText`, {
    "number1": '1',
    "number2": '',
    "message": '1'
    })
    setAwake(true);
  }
  */
  

  const getCfgAll = () => {
    if(!cfgAll){
      Axios.get(`${config.apiUrl}/cfgall`)
    .then(res => {
      setCfgAll(res.data[0])
    })
    }
    
  }
  getCfgAll()

  

  const handleClick = () => {
    try {
      Axios.post(`${config.authUrl}/auth/login`, values).then((res) => 
        Axios.get(`${config.authUrl}/user/${res.data.id}`, { headers: { Authorization: `Bearer ${res.data.token}` } })
        .then(res => {
          config.user = res.data.user
          Axios.post(`${config.apiUrl}/globalversion`, {globalVersion: res.data.globalVersion})
          .then(res => {
            if(res.data){
              navigate('/modulos', { replace: true });
              if(cfgAll && cfgAll.lastuser !== config.user._id && config.user.grupo !== 1){
                Axios.post(`${config.apiUrl}/cfgall`, {lastuser: config.user._id})
              }
            }else{
              window.alert('Nova atualização encontrada, feche o sistema para concluir o processo!')
            }
          })
        })
        .catch(error => {
          window.alert(error.response.data.msg)
        })
      ).catch(error => {
        window.alert(error.response.data.msg)
      })  
    } catch (e){
      window.alert(e)
    }

    try {
      Axios.post(`${config.authUrl2}/auth/login`, values).then((res) => 
        Axios.get(`${config.authUrl2}/user/${res.data.id}`, { headers: { Authorization: `Bearer ${res.data.token}` } })
        .then(res => {
          config.user = res.data.user
          Axios.post(`${config.apiUrl}/globalversion`, {globalVersion: res.data.globalVersion})
          .then(res => {
            if(res.data){
              navigate('/modulos', { replace: true });
              if(cfgAll && cfgAll.lastuser !== config.user._id && config.user.grupo !== 1){
                Axios.post(`${config.apiUrl}/cfgall`, {lastuser: config.user._id})
              }
            }else{
              window.alert('Nova atualização encontrada, feche o sistema para concluir o processo!')
            }
          })
        })
        .catch(error => {
          window.alert(error.response.data.msg)
        })
      ).catch(error => {
        window.alert(error.response.data.msg)
      })  
    } catch (e){
      window.alert(e)
    }
        
  };

  const handleClick2 = () => {
    if(values.password === values.confirmpassword){
      Axios.post(`${config.authUrl}/auth/primeirologin`, values).then((res) => 
        Axios.get(`${config.authUrl}/user/${res.data.id}`, { headers: { Authorization: `Bearer ${res.data.token}` } })
        .then(res => {
          config.user = res.data.user
          navigate('/modulos', { replace: true });
          if(cfgAll && cfgAll.lastuser !== config.user._id && config.user.grupo !== 1){
            Axios.post(`${config.apiUrl}/cfgall`, {lastuser: config.user._id})
          }
        })
        .catch(error => {
          window.alert(error.response.data.msg)
        })
      ).catch(error => {
        window.alert(error.response.data.msg)
      })  
    }else{
      window.alert('As senhas precisam serem preenchidas igualmente')
    }
      
};

  const handleChange = (prop) => (event) => {
    setValues({ ...values, [prop]: event.target.value });    
  };

  const handleKeyPress = (event) => {
   if(!primeiroLogin){
    if(event.key === 'Enter'){
      handleClick();
    }
   }
   if(primeiroLogin){
    if(event.key === 'Enter'){
      handleClick2();
    }
   }
    
  }

  const handleClickCheck = () => {
    setPrimeiroLogin(!primeiroLogin)
  }

  return (
    <>
      <Stack spacing={3}>
        <TextField name="email" label="Email" onChange={handleChange("email")}/>

        <TextField
          name="password"
          label="Senha"
          type={showPassword ? 'text' : 'password'}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end">
                <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                  <Iconify icon={showPassword ? 'eva:eye-fill' : 'eva:eye-off-fill'} />
                </IconButton>
              </InputAdornment>
            ),
          }}
          onChange={handleChange("password")}
          onKeyDown={handleKeyPress}
        />

        {primeiroLogin ? 
          <TextField
          name="confirmpassword"
          label="Confirme a Senha"
          type={showPassword ? 'text' : 'password'}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end">
                <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                  <Iconify icon={showPassword ? 'eva:eye-fill' : 'eva:eye-off-fill'} />
                </IconButton>
              </InputAdornment>
            ),
          }}
          onChange={handleChange("confirmpassword")}
          onKeyDown={handleKeyPress}
        />
        : null }
      </Stack>

      <Stack direction="row" alignItems="center" justifyContent="left" sx={{ my: 2 }}>
        <Checkbox name="remember" label="Primeiro Login?" onChange={handleClickCheck}/>
        <Typography variant="subtitle2">
          Primeiro Login?
        </Typography>
          
        
      </Stack>

      <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ my: 2 }}>
        {
          !primeiroLogin ?
            <LoadingButton fullWidth size="large" type="submit" variant="contained" onClick={handleClick}>
              Login
            </LoadingButton>
            :
            <LoadingButton fullWidth size="large" type="submit" variant="contained" onClick={handleClick2}>
              Salvar Senha
            </LoadingButton>
        }
        
      </Stack>

      
    </>
  );
}
