import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import Axios from 'axios';


// @mui
import {  Grid, 
          Container, 
          Typography, 
          Button, 
          FormControl, 
          // Input, 
          OutlinedInput, 
          InputLabel, 
          InputAdornment, 
          Select, 
          MenuItem, 
          TextField,
          IconButton,
         } from '@mui/material';

import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';      


import config from '../config.json'
import getConfig from '../configService';

config.apiUrl= await getConfig()

// ----------------------------------------------------------------------

export default function ConexaoPage() {
  const [isConnected, setIsConnected] = useState();
  const [DbIsConnected, setDbIsConnected] = useState(false);
  const [loading, setLoading] = useState(false);
  const [qrCode, setQrCode] = useState(null);
  const [configData, setConfigData] = useState({
      erp: 1,
      usuario:'',
      senha:'',
      host:'',
      porta:'',
      // caminhoBanco:'',
      // caminhoBancoServerLog:'',
      caminho:'',
      caminhosl:''
  })

  const [values, setValues] = useState({
    password:'',
    usuario:'',
    showPassword: false,
  });

  useEffect(getConfigDB,[]);

  function getConfigDB() {
    Axios.get(`${config.apiUrl}/configdb`)
    .then(res => {
      setConfigData(res.data)
    })
    .catch(window.alert)
  }

  const handleChangeConfigData = (prop) => (event) => {
    setConfigData({ ...configData, [prop]: event.target.value })
  };
  
  const handleClickShowPassword = () => {
    setValues({
      ...values,
      showPassword: !values.showPassword,
    });
  };

  const testConnectionDB = () => {
    configData.grupo = config.user.grupo;
    Axios.get(`${config.apiUrl}/statusdb`, {params: configData})
    .then(res => {
      if(res.status === 200){
        setDbIsConnected(true)
      }else{
        window.alert("Erro conexão banco de dados")
      }
    })
    .catch(window.alert)
  }

  const testConnectionWP = async () => {
    setLoading(true)
    Axios.get(`${config.apiUrl}/status`)
    .then(async res => {
      console.log(res.data)
      if(res.data.connected !== true){
        setIsConnected(res.data.connected)
        setQrCode(res.data.qr_code)
        await sleep(4000);
        setLoading(true);
        testConnectionWP();
      }else{
        setIsConnected('Verificando')
        await sleep(2000);
        if(config.api !==2){
          Axios.post(`${config.apiUrl}/sendText`, {
            "number1": '3411111111',
            "number2": '',
            "message": '1'
          })
          .then(async () => {
            setIsConnected(res.data.connected)
            setQrCode(null)
            setLoading(false)
          }).catch(async () => {
            setQrCode(null)
            await sleep(5000);
            setLoading(false)
          })
        }else{
          setIsConnected(res.data.connected)
          setQrCode(null)
          setLoading(false)
        }
        
        
      }
    })
    .catch(window.alert)
  }

  /*
  // antiga nao verifica status da conexao
  const testConnectionWP2 = () => {
    setLoading(true)
    Axios.get(`${config.apiUrl}/status`)
    .then(async res => {
      console.log(res.data)
      if(res.data.connected !== true){
        setIsConnected(res.data.connected)
        setQrCode(res.data.qr_code)
        await sleep(4000);
        setLoading(true);
        testConnectionWP();
      }else{
        setIsConnected(res.data.connected)
        setQrCode(null)
        setLoading(false)
      }
    })
    .catch(window.alert)
  }
  */
 
  function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  return (
    <>
      <Helmet>
        <title> Conexão </title>
      </Helmet>

      <Container maxWidth="xl">
        <Typography variant="h4" sx={{ mb: 5 }}>
          Conexão
        </Typography>
        
        <Grid container spacing={1} justifyContent={'center'} alignContent={'center'} height={'80vh'}>              
          <Grid item xs={12} sm={6} md={5}>
            {config.user.grupo === 1 ? 
            <>
              <FormControl fullWidth>
                <InputLabel id="lb1">ERP Integração</InputLabel>
                <Select
                  labelId="lb1"
                  id="selectSistema"
                  value={configData.erp}
                  label="ERP Integração"
                  onChange={() => {}}
                >
                  <MenuItem value={1}>Explend</MenuItem>
                </Select>
              </FormControl>
              <br/><br/>
              <FormControl fullWidth>
                <TextField id="lbusuario" label="Usuário" variant="outlined" value={configData.usuario} onChange={handleChangeConfigData('usuario')}/>
              </FormControl>
              <br/><br/>
              <FormControl fullWidth>
                <InputLabel id="lb2">Senha</InputLabel>
                  <OutlinedInput
                    id="olb2"
                    type={values.showPassword ? 'text' : 'password'}
                    value={configData.senha}
                    onChange={handleChangeConfigData('senha')}
                    endAdornment={
                      <InputAdornment position="end">
                        <IconButton
                          aria-label="toggle password visibility"
                          onClick={handleClickShowPassword}
                          edge="end"
                        >
                          {values.showPassword ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    }
                    label="Senha"
                  />
              </FormControl>
              <br/><br/>       
              <FormControl fullWidth>
                <Grid container spacing={1} >
                    <Grid item xs={12} sm={6} md={5}>
                      <TextField id="lbporta" label="Porta" variant="outlined" value={configData.porta} onChange={handleChangeConfigData('porta')}/>
                    </Grid>
                    <Grid item >
                      <TextField id="lbhost" label="Host" variant="outlined" value={configData.host} onChange={handleChangeConfigData('host')}/>
                    </Grid>
                </Grid>
              </FormControl>
              <br/><br/>
              <FormControl fullWidth>
                <TextField id="lbcaminho" label="Caminho do Banco"  value={configData.caminho} onChange={handleChangeConfigData('caminhoBanco')}/>
              </FormControl>
              <br/><br/>
              <FormControl fullWidth>
                <TextField id="lbcaminhoserverlog" label="Caminho Server Log"  value={configData.caminhosl} onChange={handleChangeConfigData('caminhoBancoServerLog')}/>
              </FormControl>
              <br/><br/>
            </>
            : null}
            <br/>
            <div style={{display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
              {!DbIsConnected ? 
                <Button variant="contained" onClick={testConnectionDB}>
                  Verificar Conexão Banco de Dados
                </Button>
              :
                <Button variant="contained" color="success">
                  Banco Conectado
                </Button>
              }
            </div>
          </Grid>

          <Grid item className="notranslate"  xs={12} sm={6} md={5} sx={{display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection:'column'}}>

            {qrCode !== null ? <img src={qrCode} alt='qrcode'/> : null}
            {<br/>}
            {isConnected === true ? 
                <Button variant="contained" color="success">
                  Whatsapp Conectado
                </Button>
                : loading ? 
                  <Button variant="contained" >
                    {isConnected}
                  </Button>
                  : 
                  <Button variant="contained" onClick={testConnectionWP}>
                    Verificar Conexão Whatsapp
                  </Button>}
              
          </Grid>        
        </Grid>
        

      </Container>
    </>
  );
}
