import { Navigate, useRoutes } from 'react-router-dom';
// layouts
import DashboardLayout from './layouts/dashboard';
import SimpleLayout from './layouts/simple';

//

import Page404 from './pages/Page404';
import ConexaoPage from './pages/ConexaoPage';
import ConfiguracaoPage from './pages/ConfiguracaoPage'
import LogsPage from './pages/LogsPage'
import Login from './pages/LoginPage'
import Modulos from './pages/Modulos'
import Promocao from './pages/Promocao'
import Agendamento from './pages/Agendamento'

// ----------------------------------------------------------------------
// import Teste from './pages/Teste'

export default function Router() {

    const routes = useRoutes([
    
    
      // WebApi
      {
        path: '/',
        element: <DashboardLayout />,
        children: [
          { element: <Navigate to="/login" />, index: true },
          { path: 'conexao', element: <ConexaoPage /> },
          { path: 'configuracao', element: <ConfiguracaoPage /> },
          { path: 'logs', element: <LogsPage /> },
          { path: 'promocao', element: <Promocao /> },
          { path: 'agendamento', element: <Agendamento /> },
        ],
      },
      {
        element: <SimpleLayout />,
        children: [
          { element: <Navigate to="/conexao" />, index: true },
          { path: 'login', element: <Login /> },
          { path: 'modulos', element: <Modulos /> },
          { path: '404', element: <Page404 /> },
          { path: '*', element: <Navigate to="/404" /> },
        ],
      },
      {
        path: '*',
        element: <Navigate to="/404" replace />,
      },
      {
        path: 'login',
        element: <Navigate to="/login" replace />,
      },
      
      
    ]);

    
  
  

  return routes;
}
