import * as React from 'react';
import PropTypes from 'prop-types';
// @mui
import {  
  Box,
  Modal,
  Button,
  Stack

} from '@mui/material';



const style = {
  position: 'absolute',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  width: '50vw',
  height: '50vh',
  '@media screen and (max-width: 600px)': {
    width: '50vw', // Width de 100% para telas de celulares
    height: '50vh',
  },
  bgcolor: 'background.paper',
  border: '2px solid #000',
  boxShadow: 24,
  p: 2,
  display: 'flex',
  flexDirection: 'column',
  overflowY: 'auto',
  backgroundColor: 'azure',
  alignItems: 'center',
  justifyContent: 'center',
};

// ----------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
const ModalConfirmation = React.forwardRef((props, ref) => {
  console.log(props)
  
  return (


    <Modal
      open={props.open}
      onClose={props.onClose}
      aria-labelledby="modal-modal-title"
      aria-describedby="modal-modal-description"
      >
        <Box sx={style}>
          <Box>
            <h3>{props.texts.title}</h3>
          </Box>
          
          <p>
            {props.texts.subTitle.split('\n').map((line, index) => (
              <span key={index}>
                {line}
                <br />
              </span>
            ))}
          </p>
          <Stack direction={'row'} justifyContent={'space-between'} gap={20} mt={5}>
            <Button variant="outlined" color="error" onClick={() => props.promise.reject(new Error(false))}>
              {props.texts.cancelText}
            </Button>
            <Button variant="contained" color="success" onClick={() => props.promise.resolve(true)}>
              {props.texts.confirmText}
            </Button>
          </Stack>
          
        </Box> 
    </Modal> 
  );
})

ModalConfirmation.propTypes = {
  open: PropTypes.bool,
  onClose: PropTypes.func,
  onConfirm: PropTypes.func,
  onCancel: PropTypes.func
}

export default (ModalConfirmation);

/*

para chamar esse modal usar da seguinte forma
declarar estados para armazenar o abertura do modal e a promise de retorno da confirmacao:

const [modalConfirmation, setModalConfirmation] = useState(false)
const [modalPromise, setModalPromise] = useState(null);

onde vai abrir o modal e aguardar a confirmacao:

setModalConfirmation(true)
const promise = new Promise((resolve, reject) => {
  // Configurar a Promise no estado
  setModalPromise({ resolve, reject });
});
try {
  // Aguardar a resolução da Promise do modal
  window.alert('confirmou')
} catch (error) {
  window.alert('cancelado')
} finally {
  // Fechar o modal
  setModalConfirmation(false);
}

e o componete chama assim:
{modalConfirmation && <ModalConfirmation promise={modalPromise} title={'Deseja testar o envio da promoção?'} open={modalConfirmation} onClose={() => setModalConfirmation(false)} />}

*/