import { useNavigate } from 'react-router-dom';
import React,{ useEffect, useState } from 'react';
// react
import { Helmet } from 'react-helmet-async';
// @mui
import Grid from '@mui/material/Grid';
import Paper from '@mui/material/Paper';
import { styled } from '@mui/material/styles';
import { Typography } from '@mui/material';


import versionUpdate from './helpers/versionUpdate';

import config from '../config.json'
import getConfig from '../configService';

config.apiUrl= await getConfig()


const StyledContent = styled('div')(({ theme }) => ({
  margin: 'auto',
  minHeight: '100vh',
  display: 'flex',
  justifyContent: 'center',
  flexDirection: 'column',
  padding: theme.spacing(12, 0),
}));

const modulos = [
  {
    nome: "WebApi",
    color: "lightgreen",
    icon: "/assets/moduleIcons/webapi.png",
    target:"/conexao"
  },
  /* 
  {
    nome: "Cashback",
    color: "gold",
    icon: "/assets/moduleIcons/cashback.png",
    target:"/cashback/home"
  }
                           
  {
    nome: "Rotas",
    color: "silver",
    icon: "/assets/moduleIcons/rotas.png",
    target:"/rotas"
  },
  {
    nome: "Desks",
    color: "lightblue",
    icon: "/assets/moduleIcons/dash.png",
    target:""
  }
  */
]


// ----------------------------------------------------------------------

export default function Modulos() {
  const navigate = useNavigate();
  const [atualizado, setAtualizado] = useState(false)

  useEffect(validateUser,[])
  useEffect(() => {versao()},[])

  
  function validateUser(){
    if(!config.user._id){ 
      navigate('/', { replace: true });
    }
  }
  
  const handleClick = (target) => {
    navigate(target, { replace: true });
  };

  async function versao(){
    const atu = await versionUpdate();
    if(atu){
      setAtualizado(atu)
    }else {
      window.alert('Erro ao atualizar')
    }
    
  }
  


  return (
    <>
      <Helmet>
        <title> Módulos </title>
      </Helmet>
      
      <StyledContent>
      <Typography variant="h6" sx={{marginLeft: 2}} color={'lightgray'}>
        Selecione um módulo
      </Typography>
      <Grid sx={{ flexGrow: 1 }} container spacing={5}>
        <Grid item xs={12}>
          <Grid container justifyContent="center" spacing={5}>
            {atualizado && modulos.map((value, index) => (
              <Grid key={index} item onClick={() => {handleClick(value.target)}} sx={{mt:10}}>
                <Paper
                  sx={{
                    height: 250,
                    width: 250,
                    backgroundColor: value.color,
                    cursor: 'pointer',
                    textAlign:'center',         
                    // backgroundImage: "/assets/moduleIcons/webapi.png"           
                  }}
                >
                  <Typography variant="h4" sx={{ px: 5, color: 'white', textShadow:'black 0.1em 0.1em 0.2em'}}>
                    {value.nome}
                  </Typography>
                  <img src={value.icon} alt="logos" style={{height:200, width:200, margin:'auto'}}/>
                </Paper>
              </Grid>
            ))}
          </Grid>
        </Grid>
      </Grid>
      </StyledContent>
    </>
  );
}
